) AS v(
  id text, description text, street text, loc text, cost text, clear_run integer,
  old_title text, title text, clear_time boolean
)
WHERE e."id" = v.id
  AND ((v.description IS NOT NULL AND e."description" IS NULL)
    OR (v.street IS NOT NULL AND e."locationStreet" IS NULL AND e."locationName" IS NOT DISTINCT FROM v.loc)
    OR (v.cost IS NOT NULL AND e."cost" IS NULL)
    OR (e."runNumber" = v.clear_run AND NOT EXISTS (
      SELECT 1 FROM "RawEvent" r JOIN "Source" s ON s.id = r."sourceId"
      WHERE r."eventId" = e.id AND s.type <> 'HARRIER_CENTRAL'
    ))
    OR e."title" = v.old_title
    OR (v.clear_time AND e."startTime" = '00:00'));

UPDATE "Event" e SET "description" = v.description, "updatedAt" = NOW() AT TIME ZONE 'UTC'
FROM jsonb_to_recordset(
